from itertools import combinations
from typing import Callable, FrozenSet, List

RankFn = Callable[[FrozenSet[int]], int]

def all_subsets(E: FrozenSet[int]) -> List[FrozenSet[int]]:
    xs = sorted(E)
    return [frozenset(c) for k in range(len(xs) + 1) for c in combinations(xs, k)]

def min_obj(r1: RankFn, r2: RankFn, E: FrozenSet[int]) -> int:
    return min(r1(A) + r2(E - A) for A in all_subsets(E))

def deletion_inherits_obstruction(r1: RankFn, r2: RankFn,
                                  E: FrozenSet[int], t: int) -> str:
    base = min_obj(r1, r2, E)
    if base >= t:
        return 'NOT_AN_OBSTRUCTION'
    for e in sorted(E):
        de = min_obj(r1, r2, E - {e})
        assert de <= base
        if de >= t:
            return f'REPAIRED_BY_DELETING {e}'  # provably impossible
    return 'OBSTRUCTION_INHERITED_BY_EVERY_DELETION'

if __name__ == '__main__':
    E = frozenset({0, 1, 2})
    r1 = lambda A: min(len(A), 1)
    color = {0: 5, 1: 5, 2: 5}
    r2 = lambda A: len({color[e] for e in A})
    print(deletion_inherits_obstruction(r1, r2, E, t=2))

