from typing import Callable, FrozenSet, List, Tuple, Optional

RankFn = Callable[[FrozenSet[int]], int]

def all_subsets(E: FrozenSet[int]) -> List[FrozenSet[int]]:
    xs = sorted(E)
    return [frozenset(c) for k in range(len(xs) + 1) for c in combinations(xs, k)]

def certify_rfi(r1: RankFn, r2: RankFn, E: FrozenSet[int], t: int
                ) -> Tuple[str, int, Optional[FrozenSet[int]]]:
    best = None
    argmin: Optional[FrozenSet[int]] = None
    for A in all_subsets(E):
        v = r1(A) + r2(E - A)
        if best is None or v < best:
            best, argmin = v, A
    assert best is not None
    if best >= t:
        return ('RFI_HOLDS', best, None)
    return ('OBSTRUCTION', best, argmin)

